import re
REPAIRS={'through2035':'through 2035','Staged3now':'Staged: 3 now','cashyears':'cash years','Unstaged1year':'Unstaged one-year','with5now':'with 5 now','plant10':'plant 10','plant−8':'plant −8','goodp':'good p','Perfectstudy':'Perfect study','goodstate':'good state','badstate':'bad state','studyEV':'study EV','bestprior':'best prior','afteroptimaldecision':'after optimal decision','beforeEV':'before EV','sortedloss':'sorted loss','SortedNPV':'Sorted NPV','mean(loss':'mean(loss','fixed.7m':'fixed .7m','countryA':'country A','countryB':'country B','same20':'same 20','fullDCF':'full DCF','initialorders':'initial orders','cashneeds':'cash needs','currentchosen':'current chosen','ordersrequired':'orders required','supplynotdemand':'supply, not demand','noquantitycalculation':'no quantity calculation','Foodsupply':'Food supply','chosengenerator':'chosen generator'}
def numerical_text(v):
 if not isinstance(v,str): return v
 for old,new in REPAIRS.items(): v=v.replace(old,new)
 v=re.sub(r'(?<=[a-z])(?=[0-9])',' ',v)
 v=re.sub(r'(?<=[0-9])(?=[a-z])',' ',v)
 return v
for row in D:
 row['body']=[numerical_text(v) for v in row['body']]
 if row['table']: row['table']['rows']=[[numerical_text(v) for v in cells] for cells in row['table']['rows']]
